package com.dawnrise.academic.security.internal;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.List;
public class InternalServiceAuthenticationFilter extends OncePerRequestFilter {private final InternalServiceSecurityProperties properties;public InternalServiceAuthenticationFilter(InternalServiceSecurityProperties properties){this.properties=properties;}@Override protected boolean shouldNotFilter(HttpServletRequest request){return !request.getRequestURI().startsWith("/internal/");}@Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws IOException,ServletException{String key=request.getHeader("X-Internal-Api-Key");String service=request.getHeader("X-Service-Name");boolean validKey=equal(properties.getApiKey(),key);boolean validService=properties.getAllowedServiceNames().stream().anyMatch(value->equal(value,service));if(!validKey||!validService){SecurityContextHolder.clearContext();response.sendError(validKey?403:401,validKey?"Internal service is not allowed":"Invalid internal service credentials");return;}SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(service,null,List.of(new SimpleGrantedAuthority("ROLE_INTERNAL_SERVICE"))));chain.doFilter(request,response);}private boolean equal(String expected,String actual){return expected!=null&&actual!=null&&MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),actual.getBytes(StandardCharsets.UTF_8));}}
